export function getTop20EntitiesForSector(sector: string, allEntities: TechEntity[]): TechEntity[] {
  const seeds = SECTOR_TOP20_SEEDS[sector];
  if (!seeds) {
    return allEntities.slice(0, 20);
  }

  return seeds.map((seed, idx) => {
    const seedLower = seed.name.toLowerCase();
    const existing = allEntities.find(
      (e) =>
        e.name.toLowerCase() === seedLower ||
        e.legalName.toLowerCase() === seed.legalName.toLowerCase()
    );

    if (existing) {
      return {
        ...existing,
        country: seed.country,
        rank: idx + 1,
        previousRank: idx + 1 + (seed.vel > 10 ? 2 : seed.vel < 0 ? -1 : 0)
      };
    }

    return {
      id: `entity:${sector}_${idx + 1}_${seed.name.toLowerCase().replace(/[^a-z0-9]/g, '_')}`,
      name: seed.name,
      legalName: seed.legalName,
      category: seed.category,
      domains: seed.domains,
      country: seed.country,
      isFrontierStack: true,
      cryptoLayer: seed.cryptoLayer,
      mai: seed.mai,
      fri: seed.fri,
      subsidiariesCount: 3 + (idx % 6),
      subsidiaries: [`${seed.name} Core R&D`, `${seed.name} International Operations`],
      acquisitionsLast5Years: seed.acq5y,
      totalAcquisitions: seed.acq5y + 2,
      majorAcquisitions: [],
      rank: idx + 1,
      previousRank: idx + 1 + (seed.tag === 'HOT' ? 2 : seed.tag === 'RISING' ? 1 : seed.tag === 'COOLING' ? -2 : 0),
      movementScore: Math.round(seed.vel * 4),
      velocityScore: seed.vel,
      velocityTag: seed.tag,
      velocityTrail: [idx + 4, idx + 3, idx + 2, idx + 2, idx + 1, idx + 1],
      jurisdictions: [seed.country],
      foundedYear: 2010 + (idx % 14),
      activeAntitrustCases: [`Regulatory & Sovereign Supply Chain Audit (${seed.country})`],
      consolidationSignals: [seed.chokepoint],
      primaryChokepoint: seed.chokepoint,
      dependencyScore: seed.mai
    };
  });
}

export function getAllUniqueCatalogEntities(baseEntities: TechEntity[]): TechEntity[] {
  const map = new Map<string, TechEntity>();
  baseEntities.forEach((e) => map.set(e.name.toLowerCase(), e));

  Object.keys(SECTOR_TOP20_SEEDS).forEach((sector) => {
    const sectorEntities = getTop20EntitiesForSector(sector, baseEntities);
    sectorEntities.forEach((se) => {
      const key = se.name.toLowerCase();
      if (!map.has(key)) {
        map.set(key, se);
      }
    });
  });

  return Array.from(map.values()).map((e, i) => ({
    ...e,
    rank: i + 1
  }));
}
